window.AUTH=window.AUTH||{};window.AUTH["23-1127"]={"d":"23-1127","id":"2024/23-1127","n":"Wisconsin Bell, Inc. cv. United States, ex rel. Heath","briefs":[{"k":"petitioner","label":"Brief of petitioner Wisconsin Bell, Inc.","date":"2024-08-13","url":"https://www.supremecourt.gov/DocketPDF/23/23-1127/322319/20240813113740436_Wisconsin%20Bell%20v.%20U.S.%20ex%20rel.%20Heath%20-%20Opening%20Brief.pdf","side":"pet","n":88},{"k":"respondent","label":"Brief of respondent United States, ex rel. Todd Heath","date":"2024-09-24","url":"https://www.supremecourt.gov/DocketPDF/23/23-1127/326756/20240924134746132_23-1127BriefForRespondent.pdf","side":"res","n":98},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2024-10-01","url":"https://www.supremecourt.gov/DocketPDF/23/23-1127/327331/20241001175827463_23-1127bsacUnitedStates.pdf","side":"us","n":54},{"k":"reply","label":"Reply of petitioner Wisconsin Bell, Inc.","date":"2024-10-24","url":"https://www.supremecourt.gov/DocketPDF/23/23-1127/330157/20241024102758611_Wisconsin%20Bell%20v.%20U.S.%20ex%20rel.%20Heath%20-%20Reply%20Brief.pdf","side":"pet","n":45}],"opinion":"https://www.supremecourt.gov/opinions/24pdf/604us1r10_mlio.pdf","tr":true,"items":[{"t":"case","label":"Alabama v. King & Boozer","cite":"314 U.S. 1","y":1941,"id":"scdb/1941-009","sc":1,"by":{"0":"36, 38, 40","1":"42","2":"26","3":"17"},"q":[{"src":"brief","b":3,"text":"making a new general rule of agency law","cite":"314 U.S. 1"}]},{"t":"case","label":"Allison Engine Co. v. United States ex rel. Sanders","cite":"553 U.S. 662","y":2008,"id":"2007/07-214","sc":1,"by":{"0":"4, 18, 46"},"q":[{"src":"brief","b":0,"text":"start[s], as always, with the language of the statute.","cite":"553 U.S. at 668"}]},{"t":"case","label":"Auffmordt v. Hedden","cite":"137 U.S. 310","y":1890,"id":"scdb/1890-035","sc":1,"by":{"0":"37"}},{"t":"case","label":"Barnhart v. Peabody Coal Co.","cite":"537 U.S. 149","y":2003,"id":"2002/01-705","sc":1,"by":{"0":"28"}},{"t":"case","label":"Beecham v. United States","cite":"511 U.S. 368","y":1994,"id":"1993/93-445","sc":1,"by":{"0":"37"},"q":[{"src":"brief","b":0,"text":"possess[ ] that attribute as well.","cite":"511 U.S. 368, 371"}]},{"t":"case","label":"Biden v. Nebraska","cite":"600 U.S. 477","y":2023,"id":"2022/22-506","sc":1,"by":{"0":"35"},"q":[{"src":"brief","b":0,"text":"‘actual authority to take action designated or implied in the principal’s manifestations to the agent.’","cite":"600 U.S. 477, 513"}]},{"t":"case","label":"Branch v. United States","cite":"100 U.S. 673","y":1879,"id":"scdb/1879-161","sc":1,"by":{"0":"30","1":"25"}},{"t":"case","label":"Buckley v. Valeo","cite":"424 U.S. 1","y":1976,"id":"1975/75-436","sc":1,"by":{"0":"37, 41","3":"9"}},{"t":"case","label":"Burlington Indus., Inc. v. Ellerth","cite":"524 U.S. 742","y":1998,"id":"1997/97-569","sc":1,"by":{"0":"34","2":"23"},"q":[{"src":"brief","b":0,"text":"a useful beginning point for a discussion of general agency principles.","cite":"524 U.S. at 755"}]},{"t":"case","label":"Consumers’ Rsch. v. FCC, — F.4th —","cite":"2024 WL 3517592","y":2024,"court":"5th Cir. July 24","by":{"0":"28, 49"}},{"t":"case","label":"Consumers’ Rsch. v. FCC","cite":"67 F.4th 773","y":2023,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/67/773/","by":{"0":"28"}},{"t":"case","label":"Consumers’ Rsch. v. FCC","cite":"88 F.4th 917","y":2023,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.4th/88/917/","by":{"0":"28"}},{"t":"case","label":"Coudert v. United States","cite":"175 U.S. 178","y":1899,"id":"scdb/1899-014","sc":1,"by":{"0":"30"}},{"t":"case","label":"Davis v. Mich. Dep’t of Treasury","cite":"489 U.S. 803","y":1989,"id":"1988/87-1020","sc":1,"by":{"0":"21"}},{"t":"case","label":"Dep’t of Emp. v. United States","cite":"385 U.S. 355","y":1966,"id":"1966/78","sc":1,"by":{"0":"36","1":"43","2":"26","3":"18"}},{"t":"case","label":"Edward J. DeBartolo Corp. v. Fla. Gulf Coast Bldg. & Constr. Trades Council","cite":"485 U.S. 568","y":1988,"id":"1987/86-1461","sc":1,"by":{"0":"25"}},{"t":"case","label":"Emery v. United States","cite":"186 F.2d 900","y":1951,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/186/900/","by":{"0":"32","1":"25, 26"},"q":[{"src":"brief","b":0,"text":"held by the Government in trust","cite":"186 F.2d 900, 902"}]},{"t":"case","label":"Encino Motorcars, LLC v. Navarro","cite":"584 U.S. 79","y":2018,"id":"2017/16-1362","sc":1,"by":{"0":"19","2":"10, 12"}},{"t":"case","label":"Farmers Tel. Co. v. FCC","cite":"184 F.3d 1241","y":1999,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/184/1241/","by":{"0":"43"}},{"t":"case","label":"Fed. Crop Ins. Corp. v. Merrill","cite":"332 U.S. 380","y":1947,"id":"scdb/1947-002","sc":1,"by":{"0":"36","1":"41, 42","2":"26","3":"18"},"q":[{"src":"brief","b":1,"text":"a person isn’t an agent when the government hasn’t delegated actual authority to affect the government’s legal obligations.","cite":"332 U.S. 380"}]},{"t":"case","label":"Fischer v. United States","cite":"144 S. Ct. 2176","y":2024,"id":"2023/23-5572","sc":1,"by":{"0":"24, 37, 42","3":"5"},"q":[{"src":"brief","b":0,"text":"must give effect, if possible, to every clause and word of [the] statute.","cite":"144 S. Ct. 2176, 2183"},{"src":"brief","b":0,"text":"‘avoid[s] ascribing to one word a meaning so broad that it is inconsistent with’ ‘the company it keeps.’","cite":"144 S. Ct. at 2183"}]},{"t":"case","label":"Gallardo ex rel. Vassallo v. Marstiller","cite":"596 U.S. 420","y":2022,"id":"2021/20-1263","sc":1,"by":{"0":"23"},"q":[{"src":"brief","b":0,"text":"it easily could have drafted language to that effect.","cite":"596 U.S. 420, 429"}]},{"t":"case","label":"Heckler v. Cmty. Health Servs. of Crawford Cnty., Inc.","cite":"467 U.S. 51","y":1984,"id":"1983/83-56","sc":1,"by":{"0":"36","1":"41, 42","2":"26","3":"17, 18"}},{"t":"case","label":"Helsinn Healthcare S.A. v. Teva Pharms. USA, Inc.","cite":"586 U.S. 123","y":2019,"id":"2018/17-1229","sc":1,"by":{"0":"40"}},{"t":"case","label":"Hollingsworth v. Perry","cite":"570 U.S. 693","y":2013,"id":"2012/12-144","sc":1,"by":{"0":"38, 41, 45","1":"46, 47","2":"27, 29"},"q":[{"src":"brief","b":0,"text":"most basic features of an agency relationship.","cite":"570 U.S. at 713"},{"src":"brief","b":1,"text":"‘essential element of agency is the principal’s right to control the agent’s actions.’","cite":"570 U.S. 693, 713-14"},{"src":"brief","b":1,"text":"‘the principal’s right to control the agent’s actions.’","cite":"570 U.S. at 713"},{"src":"brief","b":2,"text":"An essential element of agency is the principal’s right to control the agent’s actions.","cite":"570 U.S. 693, 713"}]},{"t":"case","label":"Hutchins v. Wilentz, Goldman & Spitzer","cite":"253 F.3d 176","y":2001,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/253/176/","by":{"0":"39"}},{"t":"case","label":"Lebron v. Nat’l R.R. Passenger Corp.","cite":"513 U.S. 374","y":1995,"id":"1994/93-1525","sc":1,"by":{"0":"47, 49","3":"21"},"q":[{"src":"brief","b":3,"text":"prohibit[s] creation of new Government corporations without specific congressional authorization.","cite":"513 U.S. 374, 390"},{"src":"opinion","who":"Opinion of the Court (Justice Kagan)","text":"prohibit[s] [the] creation of new Government corporations without specifc congressional authorization.","cite":"513 U. S. 374, 390"}]},{"t":"case","label":"Loper Bright Enters. v. Raimondo","cite":"144 S. Ct. 2244","y":2024,"id":"2023/22-451","sc":1,"by":{"0":"21","3":"9"},"q":[{"src":"brief","b":0,"text":"if anything only underscores th[e] plain meaning","cite":"144 S. Ct. 2244, 2262"},{"src":"brief","b":3,"text":"apply their ‘judgment’ independent of the political branches when interpreting the laws those branches enact.","cite":"144 S. Ct. 2244, 2273"}]},{"t":"case","label":"McBoyle v. United States","cite":"283 U.S. 25","y":1931,"id":"scdb/1930-139","sc":1,"by":{"0":"23","1":"31, 32"},"q":[{"src":"brief","b":1,"text":"in everyday speech ‘vehicle’ calls up the picture of a thing moving on land.","cite":"283 U.S. 25, 26"}]},{"t":"case","label":"Meyer v. Holley","cite":"537 U.S. 280","y":2003,"id":"2002/01-1120","sc":1,"by":{"0":"34, 35, 40","1":"38, 41, 46","3":"15"}},{"t":"case","label":"Percoco v. United States","cite":"598 U.S. 319","y":2023,"id":"2022/21-1158","sc":1,"by":{"0":"34"}},{"t":"case","label":"Rainwater v. United States","cite":"356 U.S. 590","y":1958,"id":"1957/276","sc":1,"by":{"0":"3, 25, 39, 42, 47, 49","2":"10, 19","3":"12"},"q":[{"src":"brief","b":0,"text":"[t]o put a stop to the plunder—and more generally, to ‘protect the funds and property of the Government.’","cite":"356 U.S. 590, 592"},{"src":"brief","b":0,"text":"protect[ing] the funds and property of the Government.","cite":"356 U.S. at 592"},{"src":"brief","b":2,"text":"the particular form, or function, of the government instrumentality upon which [the] claims were made,","cite":"356 U.S. 590, 592"},{"src":"brief","b":2,"text":"the funds and property of the Government.","cite":"356 U.S. at 592"},{"src":"brief","b":3,"text":"to protect the funds and property of the Government.","cite":"356 U.S. 590, 592"}]},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"by":{"0":"38"}},{"t":"case","label":"Sec. Inv. Prot. Corp. v. Barbour","cite":"421 U.S. 412","y":1975,"id":"1974/73-2055","sc":1,"by":{"0":"44"}},{"t":"case","label":"Smyer v. United States","cite":"273 U.S. 333","y":1927,"id":"scdb/1926-158","sc":1,"by":{"0":"31"},"q":[{"src":"brief","b":0,"text":"clear distinction between public money and * * * sums of money received by an employee of the office charged with the specific duty of transmitting them to their real owners.","cite":"273 U.S. 333, 337"}]},{"t":"case","label":"Snyder v. United States","cite":"144 S. Ct. 1947","y":2024,"id":"2023/23-108","sc":1,"by":{"0":"21, 39"}},{"t":"case","label":"Sw. Airlines Co. v. Saxon","cite":"596 U.S. 450","y":2022,"url":"https://supreme.justia.com/cases/federal/us/596/450/","sc":1,"by":{"0":"19, 37"}},{"t":"case","label":"Taggart v. Lorenzen","cite":"587 U.S. 554","y":2019,"id":"2018/18-489","sc":1,"by":{"0":"34"}},{"t":"case","label":"TransUnion LLC v. Ramirez","cite":"594 U.S. 413","y":2021,"id":"2020/20-297","sc":1,"by":{"0":"26"},"q":[{"src":"brief","b":0,"text":"not only would violate Article III but also would infringe on the Executive Branch’s Article II authority.","cite":"594 U.S. 413, 429"}]},{"t":"case","label":"United States ex rel. Adams v. Aurora Loan Servs., Inc.","cite":"813 F.3d 1259","y":2016,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/813/1259/","by":{"0":"44"}},{"t":"case","label":"United States ex rel. DRC, Inc. v. Custer Battles, LLC","cite":"562 F.3d 295","y":2009,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/562/295/","by":{"0":"19"},"q":[{"src":"brief","b":0,"text":"[a] grantee is one to whom the money is given.","cite":"562 F.3d 295, 304"}]},{"t":"case","label":"United States ex rel. Polansky v. Exec. Health Res., Inc.","cite":"599 U.S. 419","y":2023,"id":"2022/21-1052","sc":1,"by":{"0":"3, 4, 26","2":"4, 31"},"q":[{"src":"brief","b":0,"text":"imposed civil liability for many deceptive practices meant to appropriate government assets.","cite":"599 U.S. 419, 424"},{"src":"brief","b":2,"text":"tangential to the constitutional questions at stake.","cite":"599 U.S. 419, 452 n.3"},{"src":"opinion","who":"Opinion of the Court (Justice Kagan)","text":"`protect the funds and property of the Government.'","cite":"599 U. S. 419, 424"}]},{"t":"case","label":"United States ex rel. Shupe v. Cisco Sys., Inc.","cite":"759 F.3d 379","y":2014,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/759/379/","by":{"0":"27, 28, 42, 43, 45","1":"17","3":"20"},"q":[{"src":"brief","b":0,"text":"explicitly a private corporation owned by an industry trade group,","cite":"759 F.3d 379, 387"},{"src":"brief","b":1,"text":"the Government ‘provides any portion’ of the money requested … when United States Treasury dollars flow to the defrauded entity.","cite":"759 F.3d 379, 383"},{"src":"opinion","who":"Opinion of the Court (Justice Kagan)","text":"unsupported by the Page Proof Pending Publication cases interpreting the FCA.","cite":"759 F. 3d 379, 383"}]},{"t":"case","label":"United States ex rel. Totten v. Bombardier Corp.","cite":"380 F.3d 488","y":2004,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/380/488/","by":{"0":"4, 29, 49","2":"15","3":"6"},"q":[{"src":"brief","b":3,"text":"Congress’ use of a verb tense is significant.","cite":"380 F.3d 488, 493"}]},{"t":"case","label":"United States v. Aiello","cite":"912 F.2d 4","y":1990,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/912/4/","by":{"0":"31","1":"25"}},{"t":"case","label":"United States v. Arthrex, Inc.","cite":"594 U.S. 1","y":2021,"id":"2020/19-1434","sc":1,"by":{"0":"37, 41","3":"20"},"q":[{"src":"brief","b":0,"text":"significant authority pursuant to the laws of the United States.","cite":"594 U.S. 1, 13"}]},{"t":"case","label":"United States v. Cohn","cite":"270 U.S. 339","y":1926,"id":"scdb/1925-078","sc":1,"by":{"0":"30","1":"24","3":"12"},"q":[{"src":"argument","who":"Ms. Ho","text":"And, in our case, whether you're talking about the contributions or you're talking about the debt, the settlement, the restitution, all of which is owed to the Administrative Company, all of which is being paid by the private carriers, and the government's role, as this Court said in the Cohn case, right, money or property that is just in the government's hands for temporary possession before it's being returned to its rightful owner is not public money or public funds or endangering the public fisc --"}]},{"t":"case","label":"United States v. Neifert-White Co.","cite":"390 U.S. 228","y":1968,"id":"1967/267","sc":1,"by":{"0":"21, 30","3":"4, 7"},"q":[{"src":"brief","b":0,"text":"all fraudulent attempts to cause the Government to pay out sums of money.","cite":"390 U.S. 228, 232-33"}]},{"t":"case","label":"United States v. New Mexico","cite":"455 U.S. 720","y":1982,"id":"1981/80-702","sc":1,"by":{"0":"36","1":"43","2":"26","3":"17"},"q":[{"src":"brief","b":0,"text":"demands [made] directly on the Federal Government,","cite":"455 U.S. 720, 735"},{"src":"brief","b":1,"text":"more than the invocation of traditional agency notions.","cite":"455 U.S. 720, 735-36"},{"src":"brief","b":2,"text":"a finding of constitutional tax immunity requires something more than the invocation of traditional agency notions.","cite":"455 U.S. at 736"}]},{"t":"case","label":"Universal Health Servs., Inc. v. United States ex rel. Escobar","cite":"579 U.S. 176","y":2016,"id":"2015/15-7","sc":1,"by":{"0":"34","2":"12"},"q":[{"src":"brief","b":0,"text":"settled principle of interpretation that, absent other indication, Congress intends to incorporate the well-settled meaning of the common-law terms it uses","cite":"579 U.S. 176, 187"},{"src":"argument","who":"Mr. Singh","text":"FCC mandates also determine carriers' obligations to contribute to the Universal Service Fund. Those mandates are how the government provided funds to this program, and it doesn't matter that the government routed the funds directly from the carriers to the Universal Service Fund instead of requiring an unnecessary detour through federal Treasury accounts because the False Claims Act's applicability doesn't turn on bookkeeping conventions, which is also a point Ms."},{"src":"argument","who":"Mr. Singh","text":"And so, when that money is not available because fraud depletes the Universal Service Fund, there is less money on hand to pay the beneficiaries that the government is trying to provide affordable telecommunication services to."},{"src":"argument","who":"Mr. Singh","text":"As the Court may be aware, there are other cases pending about the validity of the Universal Service Fund structure, precisely under doctrines like non-delegation, that go to some of the concerns you're raising."}]},{"t":"case","label":"Varney v. Warehime","cite":"147 F.2d 238","y":1945,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/147/238/","by":{"0":"31"}},{"t":"case","label":"Vt. Agency of Nat. Res. v. United States ex rel. Stevens","cite":"529 U.S. 765","y":2000,"id":"1999/98-1828","sc":1,"by":{"0":"4, 26","1":"36, 37","2":"32","3":"9"},"q":[{"src":"brief","b":0,"text":"3 times the amount of damages which the Government sustains,","cite":"529 U.S. 765, 784"},{"src":"brief","b":0,"text":"a partial assignment of the Government’s damages claim","cite":"529 U.S. at 773"},{"src":"brief","b":3,"text":"proprietary injury resulting from the alleged fraud.","cite":"529 U.S. 765, 771"}]},{"t":"case","label":"Young-Montenay, Inc. v. United States","cite":"15 F.3d 1040","y":1994,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/15/1040/","by":{"0":"39"}},{"t":"usc","label":"26 U.S.C. § 9702","url":"https://www.law.cornell.edu/uscode/text/26/9702","by":{"0":"28"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","by":{"0":"1"}},{"t":"usc","label":"31 U.S.C. § 705","url":"https://www.law.cornell.edu/uscode/text/31/705","stext":{"head":"§705. Inspector General for the Government Accountability Office","paras":[[0,"(a) Establishment of Office.—There is established an Office of the Inspector General in the Government Accountability Office, to—"],[1,"(1) conduct and supervise audits consistent with generally accepted government auditing standards and investigations relating to the Government Accountability Office;"],[1,"(2) provide leadership and coordination and recommend policies, to promote economy, efficiency, and effectiveness in the Government Accountability Office; and"],[1,"(3) keep the Comptroller General and Congress fully and currently informed concerning fraud and other serious problems, abuses, and deficiencies relating to the administration of programs and operations of the Government Accountability Office."],[0,"(b) Appointment, Supervision, and Removal.—"],[1,"(1) The Office of the Inspector General shall be headed by an Inspector General, who shall be appointed by the Comptroller General without regard to political affiliation and solely on the basis of integrity and demonstrated ability in accounting, auditing, financial analysis, law, management analysis, public administration, or investigations. The Inspector General shall report to, and be under the general supervision of, the Comptroller General."],[1,"(2)(A) The Inspector General may be removed from office by the Comptroller General."],[1,"(B) If the Inspector General is removed from office or is transferred to another position or location within the Government Accountability Office, the Comptroller General shall communicate in writing the substantive rationale, including detailed and case-specific reasons, for any such removal or transfer to both Houses of Congress (including to the appropriate congressional committees), not later than 30 days before the removal or transfer."],[1,"(C) If there is an open or completed inquiry into the Inspector General that relates to the removal or transfer of the Inspector General under subparagraph (A), the written communication required under subparagraph (B) shall—"],[2,"(i) identify each entity that is conducting, or that conducted, the inquiry; and"],[2,"(ii) in the case of a completed inquiry, contain the findings made during the inquiry."],[1,"(D) Nothing in this paragraph shall prohibit a personnel action otherwise authorized by law, other than transfer or removal."],[1,"(3)(A) Subject to the other provisions of this paragraph, only the Comptroller General may place the Inspector General on non-duty status."],[1,"(B) If the Comptroller General places the Inspector General on non-duty status, the Comptroller General shall communicate in writing the substantive rationale, including detailed and case-specific reasons, for the change in status to both Houses of Congress (including to the appropriate congressional committees) not later than 15 days before the date on which the change in status takes effect, except that the Comptroller General may submit that communication not later than the date on which the change in status takes effect if—"],[2,"(i) the Comptroller General has made a determination that the continued presence of the Inspector General in the workplace poses a specific threat; and"],[2,"(ii) in the communication, the Comptroller General includes a report on the determination described in clause (i), which shall include—"],[3,"(I) the substantive rationale, including detailed and case-specific reasons, for the determination made under clause (i);"],[3,"(II) an identification of each entity that is conducting, or that conducted, any inquiry upon which the determination under clause (i) was made; and"],[3,"(III) in the case of an inquiry described in subclause (II) that is completed, the findings made during that inquiry."],[1,"(C) The Comptroller General may not place the Inspector General on non-duty status during the 30-day period preceding the date on which the Inspector General is removed or transferred under paragraph (2)(A) unless the Comptroller General—"],[2,"(i) has made a determination that the continued presence of the Inspector General in the workplace poses a specific threat; and"],[2,"(ii) not later than the date on which the change in status takes effect, submits to both Houses of Congress (including to the appropriate congressional committees) a written communication that contains the information required under subparagraph (B), including the report required under clause (ii) of that subparagraph."],[1,"(D) Nothing in this paragraph may be construed to limit or otherwise modify any statutory protection that is afforded to the Inspector General or a personnel action that is otherwise authorized by law."],[1,"(4) The Inspector General shall be paid at an annual rate of pay equal to $5,000 less than the annual rate of pay of the Comptroller General, and may not receive any cash award or bonus, including any award under chapter 45 of title 5."],[0,"(c) Authority of Inspector General.—In addition to the authority otherwise provided by this section, the Inspector General, in carrying out the provisions of this section, may—"],[1,"(1) have access to all records, reports, audits, reviews, documents, papers, recommendations, or other material that relate to programs and operations of the Government Accountability Office;"],[1,"(2) make such investigations and reports relating to the administration of the programs and operations of the Government Accountability Office as are, in the judgment of the Inspector General, necessary or desirable;"],[1,"(3) request such documents and information as may be necessary for carrying out the duties and responsibilities provided by this section from any Federal agency;"],[1,"(4) in the performance of the functions assigned by this section, obtain all information, documents, reports, answers, records, accounts, papers, and other data and documentary evidence from a person not in the United States Government or from a Federal agency, to the same extent and in the same manner as the Comptroller General under the authority and procedures available to the Comptroller General in section 716 of this title;"],[1,"(5) administer to or take from any person an oath, affirmation, or affidavit, whenever necessary in the performance of the functions assigned by this section, which oath, affirmation, or affidavit when administered or taken by or before an employee of the Office of Inspector General designated by the Inspector General shall have the same force and effect as if administered or taken by or before an officer having a seal;"],[1,"(6) have direct and prompt access to the Comptroller General when necessary for any purpose pertaining to the performance of functions and responsibilities under this section;"],[1,"(7) report expeditiously to the Attorney General whenever the Inspector General has reasonable grounds to believe there has been a violation of Federal criminal law; and"],[1,"(8) provide copies of all reports to the Audit Advisory Committee of the Government Accountability Office and provide such additional information in connection with such reports as is requested by the Committee."],[0,"(d) Complaints by Employees.—"],[1,"(1) The Inspector General—"],[2,"(A) subject to subparagraph (B), may receive, review, and investigate, as the Inspector General considers appropriate, complaints or information from an employee of the Government Accountability Office concerning the possible existence of an activity constituting a violation of any law, rule, or regulation, mismanagement, or a gross waste of funds; and"],[2,"(B) shall refer complaints or information concerning violations of personnel law, rules, or regulations to established investigative and adjudicative entities of the Government Accountability Office."],[1,"(2) The Inspector General shall not, after receipt of a complaint or information from an employee, disclose the identity of the employee without the consent of the employee, unless the Inspector General determines such disclosure is unavoidable during the course of the investigation."],[1,"(3) Any employee who has authority to take, direct others to take, recommend, or approve any personnel action, shall not, with respect to such authority, take or threaten to take any action against any employee as a reprisal for making a complaint or disclosing information to the Inspector General, unless the complaint was made or the information disclosed with the knowledge that it was false or with willful disregard for its truth or falsity."],[0,"(e) Semiannual Reports.—(1) The Inspector General shall submit semiannual reports summarizing the activities of the Office of the Inspector General to the Comptroller General. Such reports shall include, but need not be limited to—"],[1,"(A) a summary of each significant report made during the reporting period, including a description of significant problems, abuses, and deficiencies disclosed by such report;"],[1,"(B) a description of the recommendations for corrective action made with respect to significant problems, abuses, or deficiencies described pursuant to subparagraph (A);"],[1,"(C) a summary of the progress made in implementing such corrective action described pursuant to subparagraph (B); and"],[1,"(D) information concerning any disagreement the Comptroller General has with a recommendation of the Inspector General."],[0,"(2) The Comptroller General shall transmit the semiannual reports of the Inspector General, together with any comments the Comptroller General considers appropriate, to Congress within 30 days after receipt of such reports."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/31/705?type=usc&year=mostrecent&link-type=html"},"by":{"0":"20","3":"4"}},{"t":"usc","label":"31 U.S.C. § 3729","url":"https://www.law.cornell.edu/uscode/text/31/3729","subs":["(2008)","(a)(1)(A)","(b)(2)(A)","(c)(1986)","(a)(1)(B)","(b)(2)(A)(i)","(b)(2)(A)(ii)","(b)(2)(A)(ii)(I)","(c)(2006)"],"stext":{"head":"§3729. False claims","paras":[[0,"(a) Liability for Certain Acts.—"],[1,"(1) In general.—Subject to paragraph (2), any person who—"],[2,"(A) knowingly presents, or causes to be presented, a false or fraudulent claim for payment or approval;"],[2,"(B) knowingly makes, uses, or causes to be made or used, a false record or statement material to a false or fraudulent claim;"],[2,"(C) conspires to commit a violation of subparagraph (A), (B), (D), (E), (F), or (G);"],[2,"(D) has possession, custody, or control of property or money used, or to be used, by the Government and knowingly delivers, or causes to be delivered, less than all of that money or property;"],[2,"(E) is authorized to make or deliver a document certifying receipt of property used, or to be used, by the Government and, intending to defraud the Government, makes or delivers the receipt without completely knowing that the information on the receipt is true;"],[2,"(F) knowingly buys, or receives as a pledge of an obligation or debt, public property from an officer or employee of the Government, or a member of the Armed Forces, who lawfully may not sell or pledge property; or"],[2,"(G) knowingly makes, uses, or causes to be made or used, a false record or statement material to an obligation to pay or transmit money or property to the Government, or knowingly conceals or knowingly and improperly avoids or decreases an obligation to pay or transmit money or property to the Government,"],[1,"is liable to the United States Government for a civil penalty of not less than $5,000 and not more than $10,000, as adjusted by the Federal Civil Penalties Inflation Adjustment Act of 1990 (28 U.S.C. 2461 note; Public Law 104–410 1), plus 3 times the amount of damages which the Government sustains because of the act of that person."],[1,"(2) Reduced damages.—If the court finds that—"],[2,"(A) the person committing the violation of this subsection furnished officials of the United States responsible for investigating false claims violations with all information known to such person about the violation within 30 days after the date on which the defendant first obtained the information;"],[2,"(B) such person fully cooperated with any Government investigation of such violation; and"],[2,"(C) at the time such person furnished the United States with the information about the violation, no criminal prosecution, civil action, or administrative action had commenced under this title with respect to such violation, and the person did not have actual knowledge of the existence of an investigation into such violation,"],[1,"the court may assess not less than 2 times the amount of damages which the Government sustains because of the act of that person."],[1,"(3) Costs of civil actions.—A person violating this subsection shall also be liable to the United States Government for the costs of a civil action brought to recover any such penalty or damages."],[0,"(b) Definitions.—For purposes of this section—"],[1,"(1) the terms \"knowing\" and \"knowingly\"—"],[2,"(A) mean that a person, with respect to information—"],[3,"(i) has actual knowledge of the information;"],[3,"(ii) acts in deliberate ignorance of the truth or falsity of the information; or"],[3,"(iii) acts in reckless disregard of the truth or falsity of the information; and"],[2,"(B) require no proof of specific intent to defraud;"],[1,"(2) the term \"claim\"—"],[2,"(A) means any request or demand, whether under a contract or otherwise, for money or property and whether or not the United States has title to the money or property, that—"],[3,"(i) is presented to an officer, employee, or agent of the United States; or"],[3,"(ii) is made to a contractor, grantee, or other recipient, if the money or property is to be spent or used on the Government's behalf or to advance a Government program or interest, and if the United States Government—"],[4,"(I) provides or has provided any portion of the money or property requested or demanded; or"],[4,"(II) will reimburse such contractor, grantee, or other recipient for any portion of the money or property which is requested or demanded; and"],[2,"(B) does not include requests or demands for money or property that the Government has paid to an individual as compensation for Federal employment or as an income subsidy with no restrictions on that individual's use of the money or property;"],[1,"(3) the term \"obligation\" means an established duty, whether or not fixed, arising from an express or implied contractual, grantor-grantee, or licensor-licensee relationship, from a fee-based or similar relationship, from statute or regulation, or from the retention of any overpayment; and"],[1,"(4) the term \"material\" means having a natural tendency to influence, or be capable of influencing, the payment or receipt of money or property."],[0,"(c) Exemption From Disclosure.—Any information furnished pursuant to subsection (a)(2) shall be exempt from disclosure under section 552 of title 5."],[0,"(d) Exclusion.—This section does not apply to claims, records, or statements made under the Internal Revenue Code of 1986."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/31/3729?type=usc&year=mostrecent&link-type=html"},"by":{"0":"1, 4, 5, 13, 15, 16, 18, 19, 20, 21, 24, 25, 32, 33, 34, 37, 38, 39, 1, 4, 18, 19, 20, 21, 24, 25","1":"8, 27, 1, 9, 10, 15, 16, 19, 27, 33, 37, 38, 45, 8, 9, 16","2":"4, 32, 4, 32, 4, 32, 4, 32, 4, 32, 4, 32, 4, 32","3":"5, 6, 13, 5"},"q":[{"src":"brief","b":0,"text":"the amount of damages which the Government sustains,","cite":"31 U.S.C. § 3729(a)"},{"src":"brief","b":0,"text":"officer, employee, or agent of the United States,","cite":"31 U.S.C. § 3729(b)(2)(A)(i)"},{"src":"brief","b":1,"text":"Government … provides or has provided any portion of the money or property requested or demanded.","cite":"31 U.S.C. § 3729(b)(2)(A)"},{"src":"brief","b":1,"text":"whether or not the United States has title to the money,","cite":"31 U.S.C. § 3729(b)(2)(A)"},{"src":"brief","b":2,"text":"whether or not the United States has title to the money","cite":"31 U.S.C. 3729(b)(2)(A)"},{"src":"brief","b":2,"text":"provides or has provided any portion of the money * * * requested or demanded.","cite":"31 U.S.C. 3729(b)(2)(A)(ii)(I)"},{"src":"brief","b":3,"text":"a contractor, grantee, or other recipient.","cite":"31 U.S.C. § 3729(b)(2)(A)(ii)"},{"src":"brief","b":3,"text":"3 times the amount of damages which the Government sustains.","cite":"31 U.S.C. § 3729(a)(1)"}]},{"t":"usc","label":"31 U.S.C. § 3730","url":"https://www.law.cornell.edu/uscode/text/31/3730","subs":["(a)","(b)","(d)"],"by":{"0":"4","2":"4, 32, 4, 4"}},{"t":"usc","label":"31 U.S.C. § 5351","url":"https://www.law.cornell.edu/uscode/text/31/5351","by":{"0":"24"}},{"t":"usc","label":"31 U.S.C. § 6707","url":"https://www.law.cornell.edu/uscode/text/31/6707","by":{"0":"24"}},{"t":"usc","label":"31 U.S.C. § 9102","url":"https://www.law.cornell.edu/uscode/text/31/9102","stext":{"head":"§9102. Establishing and acquiring corporations","paras":[[0,"An agency may establish or acquire a corporation to act as an agency only by or under a law of the United States specifically authorizing the action."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/31/9102?type=usc&year=mostrecent&link-type=html"},"by":{"0":"7, 47","2":"30","3":"21"},"q":[{"src":"brief","b":0,"text":"[a]n agency may establish or acquire a corporation to act as an agency only by or under a law of the United States specifically authorizing the action.","cite":"31 U.S.C. § 9102"},{"src":"brief","b":2,"text":"[a]n agency may establish or acquire a corporation to act as an agency only by or under a law of the United States specifically authorizing the action.","cite":"31 U.S.C. 9102"},{"src":"brief","b":3,"text":"a corporation to act as an agency.","cite":"31 U.S.C. § 9102"},{"src":"opinion","who":"Opinion of the Court (Justice Kagan)","text":"[a]n agency may establish or acquire a corporation to act as an agency only by or under a law of the United States specifcally authorizing the action.","cite":"31 U. S. C. § 9102"}]},{"t":"usc","label":"31 U.S.C. § 9105","url":"https://www.law.cornell.edu/uscode/text/31/9105","by":{"0":"20","3":"4"}},{"t":"usc","label":"47 U.S.C. § 254","url":"https://www.law.cornell.edu/uscode/text/47/254","subs":["(d)","(h)(1)(B)","(b)(4)","(b)(6)"],"stext":{"head":"§254. Universal service","paras":[[0,"(a) Procedures to review universal service requirements"],[0,"(1) Federal-State Joint Board on universal service"],[1,"Within one month after February 8, 1996, the Commission shall institute and refer to a Federal-State Joint Board under section 410(c) of this title a proceeding to recommend changes to any of its regulations in order to implement sections 214(e) of this title and this section, including the definition of the services that are supported by Federal universal service support mechanisms and a specific timetable for completion of such recommendations. In addition to the members of the Joint Board required under section 410(c) of this title, one member of such Joint Board shall be a State-appointed utility consumer advocate nominated by a national organization of State utility consumer advocates. The Joint Board shall, after notice and opportunity for public comment, make its recommendations to the Commission 9 months after February 8, 1996."],[0,"(2) Commission action"],[1,"The Commission shall initiate a single proceeding to implement the recommendations from the Joint Board required by paragraph (1) and shall complete such proceeding within 15 months after February 8, 1996. The rules established by such proceeding shall include a definition of the services that are supported by Federal universal service support mechanisms and a specific timetable for implementation. Thereafter, the Commission shall complete any proceeding to implement subsequent recommendations from any Joint Board on universal service within one year after receiving such recommendations."],[0,"(b) Universal service principles"],[0,"The Joint Board and the Commission shall base policies for the preservation and advancement of universal service on the following principles:"],[0,"(1) Quality and rates"],[1,"Quality services should be available at just, reasonable, and affordable rates."],[0,"(2) Access to advanced services"],[1,"Access to advanced telecommunications and information services should be provided in all regions of the Nation."],[0,"(3) Access in rural and high cost areas"],[1,"Consumers in all regions of the Nation, including low-income consumers and those in rural, insular, and high cost areas, should have access to telecommunications and information services, including interexchange services and advanced telecommunications and information services, that are reasonably comparable to those services provided in urban areas and that are available at rates that are reasonably comparable to rates charged for similar services in urban areas."],[0,"(4) Equitable and nondiscriminatory contributions"],[1,"All providers of telecommunications services should make an equitable and nondiscriminatory contribution to the preservation and advancement of universal service."],[0,"(5) Specific and predictable support mechanisms"],[1,"There should be specific, predictable and sufficient Federal and State mechanisms to preserve and advance universal service."],[0,"(6) Access to advanced telecommunications services for schools, health care, and libraries"],[1,"Elementary and secondary schools and classrooms, health care providers, and libraries should have access to advanced telecommunications services as described in subsection (h)."],[0,"(7) Additional principles"],[1,"Such other principles as the Joint Board and the Commission determine are necessary and appropriate for the protection of the public interest, convenience, and necessity and are consistent with this chapter."],[0,"(c) Definition"],[0,"(1) In general"],[1,"Universal service is an evolving level of telecommunications services that the Commission shall establish periodically under this section, taking into account advances in telecommunications and information technologies and services. The Joint Board in recommending, and the Commission in establishing, the definition of the services that are supported by Federal universal service support mechanisms shall consider the extent to which such telecommunications services—"],[2,"(A) are essential to education, public health, or public safety;"],[2,"(B) have, through the operation of market choices by customers, been subscribed to by a substantial majority of residential customers;"],[2,"(C) are being deployed in public telecommunications networks by telecommunications carriers; and"],[2,"(D) are consistent with the public interest, convenience, and necessity."],[0,"(2) Alterations and modifications"],[1,"The Joint Board may, from time to time, recommend to the Commission modifications in the definition of the services that are supported by Federal universal service support mechanisms."],[0,"(3) Special services"],[1,"In addition to the services included in the definition of universal service under paragraph (1), the Commission may designate additional services for such support mechanisms for schools, libraries, and health care providers for the purposes of subsection (h)."],[0,"(d) Telecommunications carrier contribution"],[0,"Every telecommunications carrier that provides interstate telecommunications services shall contribute, on an equitable and nondiscriminatory basis, to the specific, predictable, and sufficient mechanisms established by the Commission to preserve and advance universal service. The Commission may exempt a carrier or class of carriers from this requirement if the carrier's telecommunications activities are limited to such an extent that the level of such carrier's contribution to the preservation and advancement of universal service would be de minimis. Any other provider of interstate telecommunications may be required to contribute to the preservation and advancement of universal service if the public interest so requires."],[0,"(e) Universal service support"],[0,"After the date on which Commission regulations implementing this section take effect, only an eligible telecommunications carrier designated under section 214(e) of this title shall be eligible to receive specific Federal universal service support. A carrier that receives such support shall use that support only for the provision, maintenance, and upgrading of facilities and services for which the support is intended. Any such support should be explicit and sufficient to achieve the purposes of this section."],[0,"(f) State authority"],[0,"A State may adopt regulations not inconsistent with the Commission's rules to preserve and advance universal service. Every telecommunications carrier that provides intrastate telecommunications services shall contribute, on an equitable and nondiscriminatory basis, in a manner determined by the State to the preservation and advancement of universal service in that State. A State may adopt regulations to provide for additional definitions and standards to preserve and advance universal service within that State only to the extent that such regulations adopt additional specific, predictable, and sufficient mechanisms to support such definitions or standards that do not rely on or burden Federal universal service support mechanisms."],[0,"(g) Interexchange and interstate services"],[0,"Within 6 months after February 8, 1996, the Commission shall adopt rules to require that the rates charged by providers of interexchange telecommunications services to subscribers in rural and high cost areas shall be no higher than the rates charged by each such provider to its subscribers in urban areas. Such rules shall also require that a provider of interstate interexchange telecommunications services shall provide such services to its subscribers in each State at rates no higher than the rates charged to its subscribers in any other State."],[0,"(h) Telecommunications services for certain providers"],[0,"(1) In general"],[0,"(A) Health care providers for rural areas"],[2,"A telecommunications carrier shall, upon receiving a bona fide request, provide telecommunications services which are necessary for the provision of health care services in a State, including instruction relating to such services, to any public or nonprofit health care provider that serves persons who reside in rural areas in that State at rates that are reasonably comparable to rates charged for similar services in urban areas in that State. A telecommunications carrier providing service under this paragraph shall be entitled to have an amount equal to the difference, if any, between the rates for services provided to health care providers for rural areas in a State and the rates for similar services provided to other customers in comparable rural areas in that State treated as a service obligation as a part of its obligation to participate in the mechanisms to preserve and advance universal service."],[0,"(B) Educational providers and libraries"],[2,"All telecommunications carriers serving a geographic area shall, upon a bona fide request for any of its services that are within the definition of universal service under subsection (c)(3), provide such services to elementary schools, secondary schools, and libraries for educational purposes at rates less than the amounts charged for similar services to other parties. The discount shall be an amount that the Commission, with respect to interstate services, and the States, with respect to intrastate services, determine is appropriate and necessary to ensure affordable access to and use of such services by such entities. A telecommunications carrier providing service under this paragraph shall—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/47/254?type=usc&year=mostrecent&link-type=html"},"by":{"0":"6, 20, 27, 28, 47","1":"4, 22, 39, 7","2":"2, 14, 2, 13, 2, 12"},"q":[{"src":"brief","b":0,"text":"contribute * * * to the specific, predictable, and sufficient mechanisms established by the Commission to preserve and advance universal service.","cite":"47 U.S.C. § 254(d)"},{"src":"brief","b":0,"text":"mechanisms established by the Commission to preserve and advance universal service.","cite":"47 U.S.C. § 254(d)"},{"src":"brief","b":1,"text":"to preserve and advance universal service.","cite":"47 U.S.C. § 254(d)"},{"src":"opinion","who":"Opinion of the Court (Justice Kagan)","text":"to the specifc, predictable, and suffcient mechanisms established by the [FCC] to preserve and advance universal service.","cite":"47 U. S. C. § 254(d)"}]},{"t":"usc","label":"47 U.S.C. § 503","url":"https://www.law.cornell.edu/uscode/text/47/503","by":{"0":"29"}},{"t":"usc","label":"47 U.S.C. § 1752","url":"https://www.law.cornell.edu/uscode/text/47/1752","by":{"0":"20, 21","3":"3"}},{"t":"law","label":"Pub. L. No. 99-562","url":"https://www.govinfo.gov/link/statute/100/3153","by":{"0":"4","2":"5"}},{"t":"law","label":"Pub. L. No. 111-21","url":"https://www.govinfo.gov/link/plaw/111/public/21","by":{"0":"4, 5, 39","1":"9, 19","2":"5"}},{"t":"law","label":"Pub. L. No. 104-104","url":"https://www.govinfo.gov/link/plaw/104/public/104","by":{"0":"6","1":"3, 49","2":"2"}},{"t":"reg","label":"47 C.F.R. § 0.13","url":"https://www.ecfr.gov/current/title-47/section-0.13","by":{"0":"45"}},{"t":"reg","label":"47 C.F.R. § 1.80","url":"https://www.ecfr.gov/current/title-47/section-1.80","by":{"0":"29"}},{"t":"reg","label":"47 C.F.R. § 54.5","url":"https://www.ecfr.gov/current/title-47/section-54.5","by":{"0":"8, 43"}},{"t":"reg","label":"47 C.F.R. § 54.8","url":"https://www.ecfr.gov/current/title-47/section-54.8","by":{"0":"29"}},{"t":"reg","label":"47 C.F.R. § 54.500","url":"https://www.ecfr.gov/current/title-47/section-54.500","by":{"0":"7, 10","1":"7, 8"}},{"t":"reg","label":"47 C.F.R. § 54.503","url":"https://www.ecfr.gov/current/title-47/section-54.503","by":{"0":"7"}},{"t":"reg","label":"47 C.F.R. § 54.505","url":"https://www.ecfr.gov/current/title-47/section-54.505","subs":["(b)","(c)","(g)"],"by":{"0":"7, 10","1":"6, 3, 3, 3"},"q":[{"src":"brief","b":1,"text":"receive federal subsidies for 20 to 90 percent of charges on a sliding scale.","cite":"47 C.F.R. § 54.505(b)"}]},{"t":"reg","label":"47 C.F.R. § 54.511","url":"https://www.ecfr.gov/current/title-47/section-54.511","subs":["(b)"],"by":{"0":"10","1":"7"},"q":[{"src":"brief","b":1,"text":"a price above the lowest corresponding price for supported services,","cite":"47 C.F.R. § 54.511(b)"}]},{"t":"reg","label":"47 C.F.R. § 54.514","url":"https://www.ecfr.gov/current/title-47/section-54.514","subs":["(c)"],"by":{"0":"10","1":"4"}},{"t":"reg","label":"47 C.F.R. § 54.516","url":"https://www.ecfr.gov/current/title-47/section-54.516","by":{"0":"29"}},{"t":"reg","label":"47 C.F.R. § 54.701","url":"https://www.ecfr.gov/current/title-47/section-54.701","subs":["(a)","(b)"],"by":{"0":"8, 44","1":"5, 39, 5"},"q":[{"src":"brief","b":0,"text":"manifested its assent for the [Company] to act on the government’s behalf.","cite":"47 C.F.R. § 54.701(a)"},{"src":"brief","b":1,"text":"the federal universal service support mechanisms.","cite":"47 C.F.R. § 54.701(a)"}]},{"t":"reg","label":"47 C.F.R. § 54.702","url":"https://www.ecfr.gov/current/title-47/section-54.702","subs":["(b)","(c)","(e)","(f)","(n)"],"by":{"0":"8, 16, 27, 43","1":"5, 6, 13, 39, 6, 7, 41, 48, 49, 6, 6, 6","3":"7"},"q":[{"src":"brief","b":0,"text":"make policy, interpret unclear provisions of the statute or rules, or interpret the intent of Congress,","cite":"47 C.F.R. § 54.702(c)"},{"src":"brief","b":1,"text":"[a]ll of the USAC’s actions are subject to the ultimate control of the principal, the FCC, acting as part of the United States government.","cite":"47 C.F.R. § 54.702(b)"}]},{"t":"reg","label":"47 C.F.R. § 54.706","url":"https://www.ecfr.gov/current/title-47/section-54.706","subs":["(a)","(b)"],"by":{"0":"7, 27, 29","1":"22, 4, 4"},"q":[{"src":"brief","b":1,"text":"must contribute to the universal service support mechanisms.","cite":"47 C.F.R. § 54.706(a)"}]},{"t":"reg","label":"47 C.F.R. § 54.707","url":"https://www.ecfr.gov/current/title-47/section-54.707","subs":["(a)"],"by":{"0":"29","1":"7, 47","3":"20"},"q":[{"src":"brief","b":1,"text":"suspend or delay discounts, off- sets, and support amounts provided to a carrier.","cite":"47 C.F.R. § 54.707(a)"}]},{"t":"reg","label":"47 C.F.R. § 54.709","url":"https://www.ecfr.gov/current/title-47/section-54.709","subs":["(a)","(b)","(c)"],"by":{"0":"7, 9, 14, 16, 27, 28, 43","1":"4, 6, 6, 6"}},{"t":"reg","label":"47 C.F.R. § 54.717","url":"https://www.ecfr.gov/current/title-47/section-54.717","by":{"0":"45"}},{"t":"reg","label":"47 C.F.R. § 54.719","url":"https://www.ecfr.gov/current/title-47/section-54.719","by":{"0":"17, 45","1":"7, 47","3":"20"}},{"t":"reg","label":"47 C.F.R. § 69.602","url":"https://www.ecfr.gov/current/title-47/section-69.602","by":{"0":"8"}},{"t":"case","label":"Ali v. Fed. Bureau of Prisons","cite":"552 U.S. 214","y":2008,"id":"2007/06-9130","sc":1,"by":{"1":"44","2":"27"}},{"t":"case","label":"Assurance Wireless USA, LP v. Dep’t of Revenue","cite":"544 P.3d 471","y":2024,"court":"Wash.","url":"https://www.courtlistener.com/c/P.3d/544/471/","by":{"1":"43"}},{"t":"case","label":"FCC v. AT&T Inc.","cite":"562 U.S. 397","y":2011,"id":"2010/09-1279","sc":1,"by":{"1":"3"},"q":[{"src":"brief","b":1,"text":"to enhance access for schools and libraries to advanced telecommunications and information services,","cite":"562 U.S. 397, 400"}]},{"t":"case","label":"Gen. Bldg. Contractors Ass’n, Inc. v. Pennsylvania","cite":"458 U.S. 375","y":1982,"id":"1981/81-280","sc":1,"by":{"1":"41, 46","2":"24"}},{"t":"case","label":"Green v. H&R Block, Inc.","cite":"735 A.2d 1039","y":1999,"court":"Md.","url":"https://www.courtlistener.com/c/A.2d/735/1039/","by":{"1":"48"}},{"t":"case","label":"Little Sisters of the Poor Saints Peter & Paul Home v. Pennsylvania","cite":"591 U.S. 657","y":2020,"id":"2019/19-431","sc":1,"by":{"1":"29","2":"12","3":"4"},"q":[{"src":"brief","b":1,"text":"[t]o ‘provide’ means to supply, furnish, or make available.","cite":"591 U.S. 657, 676"},{"src":"brief","b":2,"text":"[t]o ‘provide’ means to supply, furnish, or make available.","cite":"591 U.S. 657, 676"}]},{"t":"case","label":"Logue v. United States","cite":"412 U.S. 521","y":1973,"id":"1972/72-656","sc":1,"by":{"1":"47, 48"}},{"t":"case","label":"Lomax v. Ortiz-Marquez","cite":"140 S. Ct. 1721","y":2020,"id":"2019/18-8369","sc":1,"by":{"1":"18, 19"},"q":[{"src":"brief","b":1,"text":"this Court may not narrow a provision’s reach by inserting words Congress chose to omit.","cite":"140 S. Ct. 1721, 1725"}]},{"t":"case","label":"Marx v. Gen. Revenue Corp.","cite":"568 U.S. 371","y":2013,"id":"2012/11-1175","sc":1,"by":{"1":"26"},"q":[{"src":"brief","b":1,"text":"in all statutory construction cases, we assume that the ordinary meaning of the statutory language accurately expresses the legislative purpose.","cite":"568 U.S. 371, 376"}]},{"t":"case","label":"Niz-Chavez v. Garland","cite":"593 U.S. 155","y":2021,"id":"2020/19-863","sc":1,"by":{"1":"26"}},{"t":"case","label":"United States ex rel. Marcus v. Hess","cite":"317 U.S. 537","y":1943,"id":"scdb/1942-043","sc":1,"by":{"1":"35","2":"10"},"q":[{"src":"brief","b":1,"text":"does not make the extent of [Government funds’] safeguard dependent upon the bookkeeping devices used for their distribution.","cite":"317 U.S. 537, 544"},{"src":"brief","b":2,"text":"the bookkeeping devices used for [the funds’] distribution,","cite":"317 U.S. 537, 544"},{"src":"opinion","who":"Opinion of the Court (Justice Kagan)","text":"to provide for restitution to the government of money taken from it by fraud.","cite":"317 U. S. 537, 551"}]},{"t":"case","label":"United States v. Am. Libr. Ass’n, Inc.","cite":"539 U.S. 194","y":2003,"id":"2002/02-361","sc":1,"by":{"1":"21","2":"13, 14","3":"7"}},{"t":"case","label":"United States v. Orleans","cite":"425 U.S. 807","y":1976,"id":"1975/75-328","sc":1,"by":{"1":"47, 48"}},{"t":"usc","label":"31 U.S.C. § 712","url":"https://www.law.cornell.edu/uscode/text/31/712","by":{"1":"18"}},{"t":"usc","label":"31 U.S.C. § 719","url":"https://www.law.cornell.edu/uscode/text/31/719","by":{"1":"18"}},{"t":"usc","label":"31 U.S.C. § 1341","url":"https://www.law.cornell.edu/uscode/text/31/1341","by":{"1":"24"}},{"t":"usc","label":"31 U.S.C. § 1346","url":"https://www.law.cornell.edu/uscode/text/31/1346","by":{"1":"18"}},{"t":"usc","label":"31 U.S.C. § 3301","url":"https://www.law.cornell.edu/uscode/text/31/3301","by":{"1":"18"}},{"t":"usc","label":"31 U.S.C. § 3302","url":"https://www.law.cornell.edu/uscode/text/31/3302","subs":["(a)"],"by":{"1":"18","2":"22"}},{"t":"usc","label":"31 U.S.C. § 3303","url":"https://www.law.cornell.edu/uscode/text/31/3303","subs":["(b)"],"by":{"1":"18"}},{"t":"usc","label":"31 U.S.C. § 3304","url":"https://www.law.cornell.edu/uscode/text/31/3304","by":{"1":"18"}},{"t":"usc","label":"31 U.S.C. § 3305","url":"https://www.law.cornell.edu/uscode/text/31/3305","by":{"1":"18"}},{"t":"usc","label":"31 U.S.C. § 3321","url":"https://www.law.cornell.edu/uscode/text/31/3321","by":{"1":"18"}},{"t":"usc","label":"31 U.S.C. § 3322","url":"https://www.law.cornell.edu/uscode/text/31/3322","by":{"1":"18"}},{"t":"usc","label":"31 U.S.C. § 3324","url":"https://www.law.cornell.edu/uscode/text/31/3324","by":{"1":"18"}},{"t":"usc","label":"31 U.S.C. § 3326","url":"https://www.law.cornell.edu/uscode/text/31/3326","subs":["(a)"],"by":{"1":"18"}},{"t":"usc","label":"31 U.S.C. § 3327","url":"https://www.law.cornell.edu/uscode/text/31/3327","by":{"1":"18"}},{"t":"usc","label":"31 U.S.C. § 3329","url":"https://www.law.cornell.edu/uscode/text/31/3329","by":{"1":"18"}},{"t":"usc","label":"31 U.S.C. § 3330","url":"https://www.law.cornell.edu/uscode/text/31/3330","by":{"1":"18"}},{"t":"usc","label":"31 U.S.C. § 3522","url":"https://www.law.cornell.edu/uscode/text/31/3522","by":{"1":"18"}},{"t":"usc","label":"31 U.S.C. § 3526","url":"https://www.law.cornell.edu/uscode/text/31/3526","by":{"1":"18"}},{"t":"usc","label":"31 U.S.C. § 3527","url":"https://www.law.cornell.edu/uscode/text/31/3527","by":{"1":"18"}},{"t":"usc","label":"31 U.S.C. § 3532","url":"https://www.law.cornell.edu/uscode/text/31/3532","by":{"1":"18"}},{"t":"usc","label":"31 U.S.C. § 3541","url":"https://www.law.cornell.edu/uscode/text/31/3541","subs":["(a)"],"by":{"1":"18"}},{"t":"usc","label":"31 U.S.C. § 3545","url":"https://www.law.cornell.edu/uscode/text/31/3545","by":{"1":"18"}},{"t":"usc","label":"31 U.S.C. § 3701","url":"https://www.law.cornell.edu/uscode/text/31/3701","subs":["(b)(1)"],"stext":{"head":"§3701. Definitions and application","paras":[[0,"(a) In this chapter—"],[1,"(1) \"administrative offset\" means withholding funds payable by the United States (including funds payable by the United States on behalf of a State government) to, or held by the United States for, a person to satisfy a claim."],[1,"(2) \"calendar quarter\" means a 3-month period beginning on January 1, April 1, July 1, or October 1."],[1,"(3) \"consumer reporting agency\" means—"],[2,"(A) a consumer reporting agency as that term is defined in section 603(f) of the Fair Credit Reporting Act (15 U.S.C. 1681a(f)); or"],[2,"(B) a person that, for money or on a cooperative basis, regularly—"],[3,"(i) gets information on consumers to give the information to a consumer reporting agency; or"],[3,"(ii) serves as a marketing agent under an arrangement allowing a third party to get the information from a consumer reporting agency."],[1,"(4) \"executive, judicial, or legislative agency\" means a department, agency, court, court administrative office, or instrumentality in the executive, judicial, or legislative branch of Government, including government corporations."],[1,"(5) \"military department\" means the Departments of the Army, Navy, and Air Force."],[1,"(6) \"system of records\" has the same meaning given that term in section 552a(a)(5) of title 5."],[1,"(7) \"uniformed services\" means the Army, Navy, Air Force, Marine Corps, Space Force, Coast Guard, Commissioned Corps of the National Oceanic and Atmospheric Administration, and Commissioned Corps of the Public Health Service."],[1,"(8) \"nontax\" means, with respect to any debt or claim, any debt or claim other than a debt or claim under the Internal Revenue Code of 1986."],[0,"(b)(1) In subchapter II of this chapter and subsection (a)(8) of this section, the term \"claim\" or \"debt\" means any amount of funds or property that has been determined by an appropriate official of the Federal Government to be owed to the United States by a person, organization, or entity other than another Federal agency. A claim includes, without limitation—"],[1,"(A) funds owed on account of loans made, insured, or guaranteed by the Government, including any deficiency or any difference between the price obtained by the Government in the sale of a property and the amount owed to the Government on a mortgage on the property,"],[1,"(B) expenditures of nonappropriated funds, including actual and administrative costs related to shoplifting, theft detection, and theft prevention,"],[1,"(C) over-payments, including payments disallowed by audits performed by the Inspector General of the agency administering the program,"],[1,"(D) any amount the United States is authorized by statute to collect for the benefit of any person,"],[1,"(E) the unpaid share of any non-Federal partner in a program involving a Federal payment and a matching, or cost-sharing, payment by the non-Federal partner,"],[1,"(F) any fines or penalties assessed by an agency; 1 and"],[1,"(G) other amounts of money or property owed to the Government."],[0,"(2) For purposes of section 3716 of this title, each of the terms \"claim\" and \"debt\" includes an amount of funds or property owed by a person to a State (including any past-due support being enforced by the State), the District of Columbia, American Samoa, Guam, the United States Virgin Islands, the Commonwealth of the Northern Mariana Islands, or the Commonwealth of Puerto Rico."],[0,"(c) In sections 3716 and 3717 of this title, the term \"person\" does not include an agency of the United States Government."],[0,"(d) Sections 3711(e) and 3716–3719 of this title do not apply to a claim or debt under, or to an amount payable under—"],[1,"(1) the Internal Revenue Code of 1986 (26 U.S.C. 1 et seq.),"],[1,"(2) the Social Security Act (42 U.S.C. 301 et seq.), except to the extent provided under sections 204(f) and 1631(b)(4) of such Act and section 3716(c) of this title, or"],[1,"(3) the tariff laws of the United States."],[0,"(e) In section 3716 of this title—"],[1,"(1) \"creditor agency\" means any agency owed a claim that seeks to collect that claim through administrative offset; and"],[1,"(2) \"payment certifying agency\" means any agency that has transmitted a voucher to a disbursing official for disbursement."],[0,"(f) In section 3711 of this title, \"private collection contractor\" means private debt collectors under contract with an agency to collect a nontax debt or claim owed the United States. The term includes private debt collectors, collection agencies, and commercial attorneys."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/31/3701?type=usc&year=mostrecent&link-type=html"},"by":{"1":"4, 21, 23, 28","3":"13"},"q":[{"src":"brief","b":1,"text":"funds … owed to the United States,","cite":"31 U.S.C. § 3701(b)(1)"},{"src":"brief","b":1,"text":"funds … owed to the United States.","cite":"31 U.S.C. § 3701(b)(1)"}]},{"t":"law","label":"Pub. L. No. 104-134","url":"https://www.govinfo.gov/link/plaw/104/public/134","by":{"1":"4"}},{"t":"law","label":"Universal Service Antideficiency Temporary Suspension Act, Pub. L. No. 108-494","url":"https://www.govinfo.gov/link/plaw/108/public/494","by":{"1":"23"}},{"t":"reg","label":"47 C.F.R. § 54.1","url":"https://www.ecfr.gov/current/title-47/section-54.1","subs":["(b)"],"by":{"1":"39"}},{"t":"reg","label":"47 C.F.R. § 54.501","url":"https://www.ecfr.gov/current/title-47/section-54.501","by":{"1":"6"}},{"t":"reg","label":"47 C.F.R. § 54.502","url":"https://www.ecfr.gov/current/title-47/section-54.502","by":{"1":"6"}},{"t":"reg","label":"47 C.F.R. § 54.507","url":"https://www.ecfr.gov/current/title-47/section-54.507","by":{"1":"6"}},{"t":"reg","label":"47 C.F.R. § 54.703","url":"https://www.ecfr.gov/current/title-47/section-54.703","by":{"1":"5"}},{"t":"reg","label":"47 C.F.R. § 54.704","url":"https://www.ecfr.gov/current/title-47/section-54.704","subs":["(b)"],"by":{"1":"5"}},{"t":"reg","label":"47 C.F.R. § 54.712","url":"https://www.ecfr.gov/current/title-47/section-54.712","by":{"1":"4"}},{"t":"reg","label":"47 C.F.R. § 54.713","url":"https://www.ecfr.gov/current/title-47/section-54.713","subs":["(c)"],"by":{"1":"4, 39"}},{"t":"reg","label":"47 C.F.R. § 54.715","url":"https://www.ecfr.gov/current/title-47/section-54.715","subs":["(a)","(b)","(c)"],"by":{"1":"6, 6, 6"},"q":[{"src":"brief","b":1,"text":"disburse[] funds under the federal universal service support mechanisms.","cite":"47 C.F.R. § 54.715(c)"}]},{"t":"reg","label":"47 C.F.R. § 54.720","url":"https://www.ecfr.gov/current/title-47/section-54.720","by":{"1":"7, 47"}},{"t":"reg","label":"47 C.F.R. § 54.721","url":"https://www.ecfr.gov/current/title-47/section-54.721","by":{"1":"7, 47"}},{"t":"reg","label":"47 C.F.R. § 54.722","url":"https://www.ecfr.gov/current/title-47/section-54.722","by":{"1":"7, 47"}},{"t":"reg","label":"47 C.F.R. § 54.723","url":"https://www.ecfr.gov/current/title-47/section-54.723","by":{"1":"7, 47"}},{"t":"reg","label":"47 C.F.R. § 54.724","url":"https://www.ecfr.gov/current/title-47/section-54.724","by":{"1":"7, 47"}},{"t":"reg","label":"47 C.F.R. § 54.725","url":"https://www.ecfr.gov/current/title-47/section-54.725","by":{"1":"7, 47"}},{"t":"case","label":"Bryson v. United States","cite":"396 U.S. 64","y":1969,"id":"1969/35","sc":1,"by":{"2":"33","3":"22"}},{"t":"case","label":"Consumers’ Research v. FCC","cite":"109 F.4th 743","y":2024,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/109/743/","by":{"2":"33"}},{"t":"case","label":"Cook County v. United States ex rel. Chandler","cite":"538 U.S. 119","y":2003,"id":"2002/01-1572","sc":1,"by":{"2":"10, 11"},"q":[{"src":"brief","b":2,"text":"Congress was concerned about pervasive fraud in ‘all Government programs.’","cite":"538 U.S. 119, 133"},{"src":"brief","b":2,"text":"to strengthen the Government’s hand in fighting false claims.","cite":"538 U.S. at 133"}]},{"t":"case","label":"Dennis v. United States","cite":"384 U.S. 855","y":1966,"id":"1965/502","sc":1,"by":{"2":"33"}},{"t":"case","label":"Jennings v. Rodriguez","cite":"583 U.S. 281","y":2018,"id":"2017/15-1204","sc":1,"by":{"2":"31"},"q":[{"src":"brief","b":2,"text":"comes into play only when, after the application of ordinary textual analysis, the statute is found to be susceptible of more than one construction.","cite":"583 U.S. 281, 296"}]},{"t":"case","label":"OPM v. Richmond","cite":"496 U.S. 414","y":1990,"id":"1989/88-1943","sc":1,"by":{"2":"27"}},{"t":"case","label":"Seila Law LLC v. CFPB","cite":"591 U.S. 197","y":2020,"url":"https://supreme.justia.com/cases/federal/us/591/197/","sc":1,"by":{"2":"32","3":"9"}},{"t":"case","label":"United States v. Azzarelli Construction Co.","cite":"647 F.2d 757","y":1981,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/647/757/","by":{"2":"20"}},{"t":"case","label":"United States v. Kapp","cite":"302 U.S. 214","y":1937,"id":"scdb/1937-005","sc":1,"by":{"2":"33"}},{"t":"const","label":"Article III","clauses":[["judicial-vesting","Judicial Vesting Clause"],["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"],["treason","Treason Clause"]],"by":{"2":"31, 32"}},{"t":"law","label":"Pub. L. No. 110-161","url":"https://www.govinfo.gov/link/plaw/110/public/161","by":{"2":"21"}},{"t":"usc","label":"31 U.S.C. § 3711","url":"https://www.law.cornell.edu/uscode/text/31/3711","by":{"2":"12"}},{"t":"usc","label":"31 U.S.C. § 3716","url":"https://www.law.cornell.edu/uscode/text/31/3716","by":{"2":"12"}},{"t":"usc","label":"31 U.S.C. § 3717","url":"https://www.law.cornell.edu/uscode/text/31/3717","by":{"2":"12"}},{"t":"usc","label":"31 U.S.C. § 9101","url":"https://www.law.cornell.edu/uscode/text/31/9101","by":{"2":"30"}},{"t":"usc","label":"47 U.S.C. § 151","url":"https://www.law.cornell.edu/uscode/text/47/151","by":{"2":"2"}},{"t":"reg","label":"69 Fed. Reg. 5718","url":"https://www.govinfo.gov/link/fr/69/5718","by":{"2":"28"}},{"t":"case","label":"Bd. of Trade of Chi. v. Hammond Elevator Co.","cite":"198 U.S. 424","y":1905,"id":"scdb/1904-048","sc":1,"by":{"3":"19"}},{"t":"case","label":"Blanca Tel. Co. v. FCC","cite":"991 F.3d 1097","y":2021,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/991/1097/","by":{"3":"13"},"q":[{"src":"brief","b":3,"text":"a different statutory scheme with different language.","cite":"991 F.3d 1097, 1114"},{"src":"argument","who":"Ms. Ho","text":"That's the Blanca case from the Tenth Circuit that we cite in our brief. The FCA limits a claim to money that the United States provides, and the Debt Collection Improvement Act defines \"claim\" more expansively without regard to its effect on the public fisc."}]},{"t":"case","label":"Ford v. United States","cite":"273 U.S. 593","y":1927,"id":"scdb/1926-171","sc":1,"by":{"3":"15"}},{"t":"case","label":"INS v. Chadha","cite":"462 U.S. 919","y":1983,"id":"1981/80-1832","sc":1,"by":{"3":"22"}},{"t":"case","label":"Medellín v. Texas","cite":"552 U.S. 491","y":2008,"id":"2007/06-984","sc":1,"by":{"3":"18"}},{"t":"case","label":"United States ex rel. DRC, Inc. v. Custer Battles, LLC","cite":"376 F. Supp. 2d 617","y":2005,"court":"E.D. Va.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/376/617/","by":{"3":"6"}},{"t":"case","label":"United States ex rel. Sanders v. Am.-Amicable Life Ins. Co. of Tex.","cite":"545 F.3d 256","y":2008,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/545/256/","by":{"3":"6, 7"},"q":[{"src":"brief","b":3,"text":"where the government discovers that a claim is false before it makes payment,","cite":"545 F.3d 256, 259"}]},{"t":"case","label":"United States ex rel. Zafirov v. Fla. Med. Assocs., LLC","cite":"2024 WL 4349242","y":2024,"court":"M.D. Fla. Sept. 30","by":{"3":"10"}},{"t":"case","label":"United States v. McNinch","cite":"356 U.S. 595","y":1958,"id":"1957/146","sc":1,"by":{"3":"12"},"q":[{"src":"brief","b":3,"text":"Congress wanted to stop th[e] plundering of the public treasury.","cite":"356 U.S. 595, 599"}]},{"t":"case","label":"United States v. Wilson","cite":"503 U.S. 329","y":1992,"id":"1991/90-1745","sc":1,"by":{"3":"6"}},{"t":"case","label":"Whitman v. Am. Trucking Ass’ns","cite":"531 U.S. 457","y":2001,"id":"2000/99-1257","sc":1,"by":{"3":"13"},"q":[{"src":"brief","b":3,"text":"alter the fundamental details of a regulatory scheme in vague terms or ancillary provisions.","cite":"531 U.S. 457, 468"}]},{"t":"usc","label":"31 U.S.C. § 101","url":"https://www.law.cornell.edu/uscode/text/31/101","by":{"3":"21"}},{"t":"usc","label":"42 U.S.C. § 659","url":"https://www.law.cornell.edu/uscode/text/42/659","stext":{"head":"§659. Consent by United States to income withholding, garnishment, and similar proceedings for enforcement of child support and alimony obligations","paras":[[0,"(a) Consent to support enforcement"],[0,"Notwithstanding any other provision of law (including section 407 of this title and section 5301 of title 38), effective January 1, 1975, moneys (the entitlement to which is based upon remuneration for employment) due from, or payable by, the United States or the District of Columbia (including any agency, subdivision, or instrumentality thereof) to any individual, including members of the Armed Forces of the United States, shall be subject, in like manner and to the same extent as if the United States or the District of Columbia were a private person, to withholding in accordance with State law enacted pursuant to subsections (a)(1) and (b) of section 666 of this title and regulations of the Secretary under such subsections, and to any other legal process brought, by a State agency administering a program under a State plan approved under this part or by an individual obligee, to enforce the legal obligation of the individual to provide child support or alimony."],[0,"(b) Consent to requirements applicable to private person"],[0,"With respect to notice to withhold income pursuant to subsection (a)(1) or (b) of section 666 of this title, or any other order or process to enforce support obligations against an individual (if the order or process contains or is accompanied by sufficient data to permit prompt identification of the individual and the moneys involved), each governmental entity specified in subsection (a) shall be subject to the same requirements as would apply if the entity were a private person, except as otherwise provided in this section."],[0,"(c) Designation of agent; response to notice or process"],[0,"(1) Designation of agent"],[1,"The head of each agency subject to this section shall—"],[2,"(A) designate an agent or agents to receive orders and accept service of process in matters relating to child support or alimony; and"],[2,"(B) annually publish in the Federal Register the designation of the agent or agents, identified by title or position, mailing address, and telephone number."],[0,"(2) Response to notice or process"],[1,"If an agent designated pursuant to paragraph (1) of this subsection receives notice pursuant to State procedures in effect pursuant to subsection (a)(1) or (b) of section 666 of this title, or is effectively served with any order, process, or interrogatory, with respect to an individual's child support or alimony payment obligations, the agent shall—"],[2,"(A) as soon as possible (but not later than 15 days) thereafter, send written notice of the notice or service (together with a copy of the notice or service) to the individual at the duty station or last-known home address of the individual;"],[2,"(B) within 30 days (or such longer period as may be prescribed by applicable State law) after receipt of a notice pursuant to such State procedures, comply with all applicable provisions of section 666 of this title; and"],[2,"(C) within 30 days (or such longer period as may be prescribed by applicable State law) after effective service of any other such order, process, or interrogatory, withhold available sums in response to the order or process, or answer the interrogatory."],[0,"(d) Priority of claims"],[0,"If a governmental entity specified in subsection (a) receives notice or is served with process, as provided in this section, concerning amounts owed by an individual to more than 1 person—"],[1,"(1) support collection under section 666(b) of this title must be given priority over any other process, as provided in section 666(b)(7) of this title;"],[1,"(2) allocation of moneys due or payable to an individual among claimants under section 666(b) of this title shall be governed by section 666(b) of this title and the regulations prescribed under such section; and"],[1,"(3) such moneys as remain after compliance with paragraphs (1) and (2) shall be available to satisfy any other such processes on a first-come, first-served basis, with any such process being satisfied out of such moneys as remain after the satisfaction of all such processes which have been previously served."],[0,"(e) No requirement to vary pay cycles"],[0,"A governmental entity that is affected by legal process served for the enforcement of an individual's child support or alimony payment obligations shall not be required to vary its normal pay and disbursement cycle in order to comply with the legal process."],[0,"(f) Relief from liability"],[0,"(1) Neither the United States, nor the government of the District of Columbia, nor any disbursing officer shall be liable with respect to any payment made from moneys due or payable from the United States to any individual pursuant to legal process regular on its face, if the payment is made in accordance with this section and the regulations issued to carry out this section."],[0,"(2) No Federal employee whose duties include taking actions necessary to comply with the requirements of subsection (a) with regard to any individual shall be subject under any law to any disciplinary action or civil or criminal liability or penalty for, or on account of, any disclosure of information made by the employee in connection with the carrying out of such actions."],[0,"(g) Regulations"],[0,"Authority to promulgate regulations for the implementation of this section shall, insofar as this section applies to moneys due from (or payable by)—"],[1,"(1) the United States (other than the legislative or judicial branches of the Federal Government) or the government of the District of Columbia, be vested in the President (or the designee of the President);"],[1,"(2) the legislative branch of the Federal Government, be vested jointly in the President pro tempore of the Senate and the Speaker of the House of Representatives (or their designees),1 and"],[1,"(3) the judicial branch of the Federal Government, be vested in the Chief Justice of the United States (or the designee of the Chief Justice)."],[0,"(h) Moneys subject to process"],[0,"(1) In general"],[1,"Subject to paragraph (2), moneys payable to an individual which are considered to be based upon remuneration for employment, for purposes of this section—"],[2,"(A) consist of—"],[3,"(i) compensation payable for personal services of the individual, whether the compensation is denominated as wages, salary, commission, bonus, pay, allowances, or otherwise (including severance pay, sick pay, and incentive pay);"],[3,"(ii) periodic benefits (including a periodic benefit as defined in section 428(h)(3) of this title) or other payments—"],[4,"(I) under the insurance system established by subchapter II;"],[4,"(II) under any other system or fund established by the United States which provides for the payment of pensions, retirement or retired pay, annuities, dependents' or survivors' benefits, or similar amounts payable on account of personal services performed by the individual or any other individual;"],[4,"(III) as compensation for death under any Federal program;"],[4,"(IV) under any Federal program established to provide \"black lung\" benefits; or"],[4,"(V) by the Secretary of Veterans Affairs as compensation for a service-connected disability paid by the Secretary to a former member of the Armed Forces who is in receipt of retired or retainer pay if the former member has waived a portion of the retired or retainer pay in order to receive such compensation;"],[3,"(iii) worker's compensation benefits paid or payable under Federal or State law;"],[3,"(iv) benefits paid or payable under the Railroad Retirement System,1 and"],[3,"(v) special benefits for certain World War II veterans payable under subchapter VIII; but"],[2,"(B) do not include any payment—"],[3,"(i) by way of reimbursement or otherwise, to defray expenses incurred by the individual in carrying out duties associated with the employment of the individual;"],[3,"(ii) as allowances for members of the uniformed services payable pursuant to chapter 7 of title 37, as prescribed by the Secretaries concerned (defined by section 101(5) of title 37) as necessary for the efficient performance of duty; or"],[3,"(iii) of periodic benefits under title 38, except as provided in subparagraph (A)(ii)(V)."],[0,"(2) Certain amounts excluded"],[1,"In determining the amount of any moneys due from, or payable by, the United States to any individual, there shall be excluded amounts which—"],[2,"(A) are owed by the individual to the United States;"],[2,"(B) are required by law to be, and are, deducted from the remuneration or other payment involved, including Federal employment taxes, and fines and forfeitures ordered by court-martial;"],[2,"(C) are properly withheld for Federal, State, or local income tax purposes, if the withholding of the amounts is authorized or required by law and if amounts withheld are not greater than would be the case if the individual claimed all dependents to which he was entitled (the withholding of additional amounts pursuant to section 3402(i) of the Internal Revenue Code of 1986 may be permitted only when the individual presents evidence of a tax obligation which supports the additional withholding);"],[2,"(D) are deducted as health insurance premiums;"],[2,"(E) are deducted as normal retirement contributions (not including amounts deducted for supplementary coverage); or"],[2,"(F) are deducted as normal life insurance premiums from salary or other remuneration for employment (not including amounts deducted for supplementary coverage)."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/659?type=usc&year=mostrecent&link-type=html"},"by":{"3":"12"},"q":[{"src":"brief","b":3,"text":"to enforce the legal obligation of the individual to provide child support.","cite":"42 U.S.C. § 659(a)"},{"src":"opinion","who":"Opinion of the Court (Justice Kagan)","text":"to enforce the legal obligation of the individual to provide child support.","cite":"42 U. S. C. § 659(a)"}]},{"t":"rule","label":"Fed. R. Civ. P. 4","url":"https://www.law.cornell.edu/rules/frcp/rule_4","by":{"3":"16"}}]};